// SigThrottle-Token - token bucket throttle demo
function Bucket(rate, cap) { this.rate = rate; this.cap = cap; this.tokens = cap; this.last = Date.now(); }
Bucket.prototype.take = function(n) {
  var now = Date.now(), el = (now - this.last) / 1000;
  this.tokens = Math.min(this.cap, this.tokens + el * this.rate); this.last = now;
  if (this.tokens >= n) { this.tokens -= n; return true; } return false;
};
var b = new Bucket(1000, 1000); // 1000 KB/s
var sent = 0, chunks = [400, 400, 400, 400];
chunks.forEach(function(c) { if (b.take(c)) sent += c; });
console.log("Tool: SigThrottle | Mechanism: distributed tokens");
console.log("Requested 1600 KB, bucket allowed: " + sent + " KB");
console.log("Throttle enforced -> PASS");

